totals = {}
for o in orders:
    totals[o["region"]] = totals.get(o["region"], 0) + float(o["amount"])
return {
  "n": len(orders),
  "unique_ids": len(set(ids)),
  "id_range": [min(ids), max(ids)],
  "statuses": sorted({o["status"] for o in orders}),
